// Whitespace-collapsed view of EN_TEXT_MAP, built once. See applyTranslations.
const EN_TEXT_MAP_NORM = Object.fromEntries(
  Object.entries(EN_TEXT_MAP).map(([k, v]) => [k.replace(/\s+/g, ' '), v])
);

function applyTranslations() {
  if (_currentLang === 'en') return; // No translation needed for English
  // Translate text content
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT);
  while (walker.nextNode()) {
    const el = walker.currentNode;
    // Only translate leaf text (no child elements with text)
    if (el.children.length === 0 || (el.childNodes.length === 1 && el.childNodes[0].nodeType === 3)) {
      const text = el.textContent.trim();
      // Look up the exact text first, then a whitespace-collapsed form. A
      // paragraph wrapped across several lines in the HTML has textContent with
      // those newlines and indentation still in it, so an exact-only lookup
      // silently fails for every multi-line string — which is most of the prose
      // on a page. Collapsing runs of whitespace makes the map indifferent to
      // how the markup happens to be wrapped.
      const key = EN_TEXT_MAP[text] || EN_TEXT_MAP_NORM[text.replace(/\s+/g, ' ')];
      if (key) {
        const translated = t(key);
        if (translated !== key) el.textContent = translated;
      }
    }
    // Placeholders
    if (el.placeholder && EN_PLACEHOLDER_MAP[el.placeholder]) {
      el.placeholder = t(EN_PLACEHOLDER_MAP[el.placeholder]);
    }
    // Titles
    if (el.title && EN_TITLE_MAP[el.title]) {
      el.title = t(EN_TITLE_MAP[el.title]);
    }
  }
}

// ── Set language ──
function setLang(lang) {
  if (!SUPPORTED_LANGS.includes(lang)) return;
  localStorage.setItem('terse-lang', lang);
  // Reload so translations apply from the clean English source HTML.
  // (applyTranslations() can only translate FROM English; reloading after saving
  // the preference guarantees the page re-initializes with the correct language.)
  window.location.reload();
}

function getLang() { return _currentLang; }
function getLangs() { return SUPPORTED_LANGS.map(l => ({ code: l, label: LANG_LABELS[l] })); }

// ── Language picker dropdown ──
function createLangPicker(anchorEl, onPick) {
  let dd = document.getElementById('langDropdown');
  if (dd) { dd.classList.toggle('hidden'); return dd; }

  dd = document.createElement('div');
  dd.id = 'langDropdown';
  dd.className = 'lang-dropdown';
  dd.style.cssText = 'position:absolute;top:100%;right:0;z-index:1000;background:var(--sf,#fff);border:1px solid var(--bd,#e5e5e5);border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.12);padding:4px 0;min-width:140px;max-height:300px;overflow-y:auto';

  for (const { code, label } of getLangs()) {
    const item = document.createElement('div');
    item.className = 'lang-item';
    item.dataset.lang = code;
    item.style.cssText = 'padding:6px 12px;font-size:12px;font-weight:500;cursor:pointer;display:flex;align-items:center;gap:6px;color:var(--t1,#333);transition:background .15s';
    item.innerHTML = '<span style="font-size:10px;opacity:0.4;min-width:50px">' + code + '</span><span>' + label + '</span>';
    if (code === _currentLang) {
      item.style.background = 'var(--acd,rgba(0,0,0,.05))';
      item.style.fontWeight = '700';
    }
    item.addEventListener('mouseenter', () => { item.style.background = 'var(--acd,rgba(0,0,0,.05))'; });
    item.addEventListener('mouseleave', () => {
      item.style.background = code === _currentLang ? 'var(--acd,rgba(0,0,0,.05))' : '';
    });
    item.addEventListener('click', () => {
      setLang(code);
      dd.classList.add('hidden');
      // Update active state
      dd.querySelectorAll('.lang-item').forEach(i => {
        i.style.background = '';
        i.style.fontWeight = '500';
      });
      item.style.background = 'var(--acd,rgba(0,0,0,.05))';
      item.style.fontWeight = '700';
      if (onPick) onPick(code);
    });
    dd.appendChild(item);
  }

  // Position relative to anchor
  const parent = anchorEl.parentElement;
  if (parent) {
    parent.style.position = 'relative';
    parent.appendChild(dd);
  } else {
    document.body.appendChild(dd);
  }

  // Close on outside click
  const closeHandler = (e) => {
    if (!e.target.closest('#langDropdown') && !e.target.closest('#btnLang')) {
      dd.classList.add('hidden');
    }
  };
  document.addEventListener('click', closeHandler);

  return dd;
}

